"""Concept A proof chain, part 0: requirements, sources, assumptions and planned tests (no claims).

    python -I redesign/qp/A/proofs/run_all.py        # gen_params_a, claims_a0..a3, then the strict build into proofs/out/

Requirement ids are REQUIREMENTS-A.md ids (A-U1 ... A-D11). Only requirements with a numeric or pass / fail basis get a
node; the ones without (settings, procedures, `—` unknowns) are listed in the docstring of run_all.py, because a requirement
no claim verifies fails the strict build.
Source `checked` = the date the value was compared with that repo file (2026-11-15, the day this graph was built). The
vendor pages behind a file's numbers are named in `where`; they were read by the file's author on the date the file gives,
not re-read here.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "proofs"))     # redesign/proofs
import proofkit as pk  # noqa: E402

kit = pk.Kit(__file__, params=["../params-A.json"], out="claims.a0_base.json")
D = "2026-11-15"
GH = "https://github.com/davinciucberkeley-collab/DBF-Combined/blob/redesign/v1/"


def src(id, title, url, where, kind="repo", checked=D, note=None):
    kit.source(id, title, kind, url=url if url.startswith("http") else "redesign/" + url, checked=checked, where=where, note=note)   # viewer links are repo-root relative


# ---------------------------------------------------------------- sources (concept A files; url given relative to redesign/)
src("SRC-A-USER", "Project constraints (root CLAUDE.md)", GH + "CLAUDE.md", "Hard constraints: $2,000, 2027-04-30, one car trunk, < 25 kg, 3-D physics pass", kind="file")
src("SRC-A-REQ", "Concept A requirements (REQUIREMENTS-A.md)", "qp/A/REQUIREMENTS-A.md", "limits of A-U1 ... A-D12; status PROPOSED, owner A2")
src("SRC-A-MASSGATE", "Mass gate, concept A (MASS-GATE.md)", "qp/A/MASS-GATE.md", "s1 verdict, s4 overrun, s5 CG, s7 QP-4 FIXES2 update")
src("SRC-A-MISSION", "Mission definition, concept A", "qp/A/MISSION.md", "s1 speeds, s2 racetrack")
src("SRC-A-MGATE", "mission_gate_a.py (mission and mass-gate arithmetic)", "qp/A/mission_gate_a.py", "items list, stall, T/W, energy and cruise-to-BATT_LOW lines", kind="code")
src("SRC-A-PROPA", "prop_a.py (APC 9x4.5MR + MN2212 model)", "qp/A/prop_a.py", "static rows of apcprop.com PER3_9x45MR.dat (read 2026-11-14 by the file's author), T-Motor MN2212 page Kv / Rm; I0, pack R and the 0.93 derate are estimates", kind="code")
