src("SRC-A-SCHEDPY", "schedule_a.py (schedule model)", "qp/A/schedule_a.py", "gates 2/5/4/3/5/3, p 0.72, crash loop 11 d, deadline 30 Apr", kind="code")
src("SRC-A-CADMASS", "CAD mass and CG (sitl/cad_mass.json)", "qp/A/sitl/cad_mass.json", "mass_basic_kg, cg_x_m, cg_y_m (regenerated by FIXES2, 2026-11-15)", kind="file")
