src("SRC-A-ASSY", "Build-sequence check output (cad/out/assembly.json, ASSEMBLY.md)", "qp/A/cad/out/ASSEMBLY.md", "35 steps, 96 of 96 parts (2026-11-15, D-194)", kind="file")
