src("SRC-A-D195SITL", "QP-5 SITL runs R5_* (sitl/results_fwd.jsonl, runs/R5_*)", "qp/A/sitl/jobs_qp5.txt", "cant 17, D-191 gains, CAD mass / CG / inertia 2026-11-15, S5010 aero; batch_qp5.sh", kind="file")
